// spec: specs/premium-store.md (раздел 3.1)
// seed: tests/seed.free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: «בוסטים» и «סופר לייק» (#4ef651)', () => {
  test('/boosts: пакеты 1/5/10, цены, бейджи, «איך זה עובד», кнопка покупки @iphone @prod-safe', async ({ page }) => {
    const purchaseRequests: string[] = [];
    page.on('request', (r) => {
      if (/purchase|payment|checkout/i.test(r.url())) purchaseRequests.push(r.url());
    });

    // 1. `/boosts`.
    await page.goto('/discover');
    await expect(page).toHaveURL(/\/discover/);
    await page.goto('/boosts');
    await expect(page.getByText('בוסטים', { exact: true }).first()).toBeVisible();

    // 2. Посмотреть экран до низа.
    const back = page.getByRole('button', { name: 'חזרה' });
    await expect(back).toBeVisible();
    const box = await back.boundingBox();
    const vw = page.viewportSize()!.width;
    expect(box!.x + box!.width / 2, 'стрелка «назад» справа').toBeGreaterThan(vw / 2);
    await expect(page.getByText('מגדיל זמנית את חשיפת הפרופיל שלך')).toBeVisible();

    const p1 = page.getByRole('radio', { name: /^1 בוסט ₪14\.90/ });
    const p5 = page.getByRole('radio', { name: /5 בוסטים ₪49\.90 ₪9\.98 ליחידה/ });
    const p10 = page.getByRole('radio', { name: /10 בוסטים ₪59\.90 ₪5\.99 ליחידה/ });
    await expect(p1).toBeVisible();
    await expect(p5).toBeVisible();
    await expect(p10).toBeVisible();
    await expect(p5).toContainText('פופולרי');
    await expect(p5).toContainText('-33%');
    await expect(p10).toContainText('-60%');

    await expect(page.getByText(/^יש לך$/)).toBeVisible();
    await expect(page.getByText(/^\d+ בוסטים$/)).toBeVisible();
    await expect(page.getByText('איך זה עובד', { exact: true })).toBeVisible();
    await expect(page.getByText('מפעילים בוסט בלחיצה אחת')).toBeVisible();
    await expect(page.getByText('מוצגים קודם למשתמשים רלוונטיים')).toBeVisible();
    await expect(page.getByText('החשיפה המוגברת היא זמנית')).toBeVisible();
    await expect(page.getByRole('button', { name: 'לקנות 5 בוסטים · ₪49.90' })).toBeVisible();
    await expect(page.locator('html')).toHaveJSProperty('scrollWidth', vw);

    // 3. Стрелка «назад».
    await back.click();
    await expect(page).not.toHaveURL(/\/boosts/);
    expect(purchaseRequests, 'запросов покупки нет').toEqual([]);
  });
});
